def test_windows_match_pyramid_tiles_and_bounds(scene, paths):
    state_text = _completed_state(scene, paths)
    result = plan_tile_update_windows(state_text, _plan_batches())

    for row in result:
        pyramid = row[5]
        windows = row[6]
        flat = [
            (level, tile[2], tile[3], tile[4], tile[5])
            for level, level_tiles in enumerate(pyramid)
            for tile in level_tiles
